let score = 0;

// Reach back to your Set node (Mapping the Fields)
const lead = $("Mapping the Fields").item.json; 

// 1. Budget Score
const budget = String(lead["Budget Range"] || "");
if (budget.includes("$10k") || budget.includes("$2k")) score += 3;

// 2. Timeline Score
const timeline = String(lead["Timeline"] || "");
if (timeline.toUpperCase() === "ASAP") {
  score += 3;
} else if (timeline.toUpperCase().includes("EXPLORING")) {
  score += 1;
}

// 3. Company Size Score
const size = String(lead["Company Size"] || "");
if (size.includes("50+")) score += 2;

// 4. Role Score
const pos = String(lead["Position"] || "");
if (pos.toUpperCase().includes("FOUNDER") || pos.toUpperCase().includes("CEO") || pos.toUpperCase().includes("MANAGER")) score += 2;

// --- LEAD STATUS LOGIC ---
let status = "LOW";
if (score >= 7) {
  status = "High";
} else if (score >= 4) {
  status = "Medium (Nurture)";
} else {
  status = "Low";
}

// Return everything to the Monday node
return {
  // ...lead,
  Monday_ID: $json.id,
  Score: score,
  Lead_Status: status
};

